<form method="post" enctype="multipart/form-data" action="<?= e(url('/admin/media/upload')) ?>" class="card p-5 mb-4 flex flex-wrap items-end gap-3" data-once><?= csrf_field() ?><div><label class="label" for="files">Upload images</label><input id="files" type="file" name="files[]" multiple accept="image/jpeg,image/png,image/webp" class="text-sm" required></div><button class="btn btn-primary"><?= icon('upload', 'w-4 h-4') ?> Upload</button><span class="hint">JPG, PNG, WebP · max 6 MB · validated, re-encoded & resized.</span></form>
<div class="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 xl:grid-cols-6 gap-3"><?php foreach ($rows as $m): ?><div class="card overflow-hidden text-xs"><div class="aspect-square bg-gray-50"><img src="<?= e(upload_url($m['path'])) ?>" class="w-full h-full object-cover" loading="lazy" alt="<?= e($m['filename']) ?>"></div><div class="p-2.5 space-y-0.5"><b class="block truncate" title="<?= e($m['filename']) ?>"><?= e($m['filename']) ?></b><div class="muted"><?= e($m['mime']) ?> · <?= round($m['size_bytes'] / 1024) ?> KB</div><div class="muted"><?= e(date('d M Y', strtotime($m['created_at']))) ?><?= $m['source'] === 'ai' ? ' · <span class="text-purple-700">AI</span>' : '' ?></div>
<div class="flex justify-between items-center pt-1"><span class="badge <?= $m['used'] ? 'bg-blue-100 text-blue-700' : 'bg-gray-100 text-gray-600' ?>"><?= $m['used'] ? 'In use' : 'Unused' ?></span><form method="post" action="<?= e(url('/admin/media/' . $m['id'] . '/delete')) ?>"><?= csrf_field() ?><button class="text-red-600 font-semibold" data-confirm="Delete this image?" <?= $m['used'] ? 'disabled style="opacity:.4"' : '' ?>>Delete</button></form></div></div></div><?php endforeach; if (!$rows): ?><div class="card p-12 text-center muted col-span-full">No images yet.</div><?php endif; ?></div>
